import {
  assignBinding,
  CONTROL_ACTIONS,
  CONTROL_LABELS,
  defaultSettings,
  keyLabel,
} from '../../platform/settings.ts';
import type { Settings, ControlAction } from '../../platform/settings.ts';
import {
  graphicsDevice,
  graphicsPreset,
  graphicsFrameRate,
  resolveGraphics,
  setGraphicsOption,
  recommendedGraphics,
} from '../../platform/graphics-settings.ts';
import type { GraphicsPreset } from '../../platform/graphics-settings.ts';
import type { GraphicsSettings } from '../../platform/graphics-settings.ts';
import type { createGraphicsQuality } from '../../platform/graphics-quality.ts';
import type { createFrameMetrics } from '../../platform/frame-metrics.ts';
import { frameMetricsText } from '../frame-metrics.ts';
type Category = 'audio' | 'controls' | 'display' | 'graphics' | 'profile';
type Page = Category | 'root';
const TITLES: Record<Page, string> = {
  root: 'Options',
  audio: 'Audio',
  controls: 'Controls',
  display: 'Display and Accessibility',
  graphics: 'Graphics',
  profile: 'Profile Management',
};
export function createOptions(
  root: HTMLElement,
  settings: Settings,
  changed: () => void,
  closed: () => void,
  tutorial?: () => void,
  graphics?: ReturnType<typeof createGraphicsQuality>,
  frameMetrics?: ReturnType<typeof createFrameMetrics>,
) {
  const doc = root.ownerDocument,
    win = doc.defaultView!;
  const content = root.querySelector<HTMLElement>('#optionsContent')!;
  const device = graphicsDevice(win);
  const presetLabel = () =>
    settings.graphics.preset === 'auto'
      ? `Auto (${recommendedGraphics(device) === 'high' ? 'High' : 'Balanced'})`
      : settings.graphics.preset[0]!.toUpperCase() + settings.graphics.preset.slice(1);
  const profiles = root.querySelector<HTMLElement>('#profileManagement')!;
  const events = new AbortController();
  let renderEvents = new AbortController();
  let page: Page = 'root',
    open = false,
    capture: ControlAction | null = null;
  let origin: HTMLElement | null = null,
    message = '';
  let historyId = '',
    session = 0;
  let afterClose: (() => void) | null = null;
  const node = <K extends keyof HTMLElementTagNameMap>(tag: K, text = '', className = '') => {
    const el = doc.createElement(tag);
    el.textContent = text;
    el.className = className;
    return el;
  };
  function button(label: string, action: () => void, className = 'btn') {
    const el = node('button', label, className);
    el.type = 'button';
    el.addEventListener('click', action, { signal: renderEvents.signal });
    return el;
  }
  function persist() {
    changed();
  }
  function setGraphic<K extends Exclude<keyof GraphicsSettings, 'preset'>>(
    key: K,
    value: GraphicsSettings[K],
  ) {
    settings.graphics = resolveGraphics(settings.graphics, device);
    setGraphicsOption(settings.graphics, key, value);
    persist();
    const preset = content.querySelector<HTMLSelectElement>('#option-graphics-preset');
    const custom = preset?.querySelector<HTMLOptionElement>('option[value="custom"]');
    if (custom) custom.disabled = false;
    if (preset) preset.value = 'custom';
  }
  function graphicSelect<
    K extends 'lighting' | 'particles' | 'weather' | 'grass' | 'scenery' | 'memory',
  >(key: K, label: string, choices: [string, GraphicsSettings[K]][]) {
    const row = node('div', '', 'option-row'),
      labelEl = node('label', label),
      input = node('select');
    labelEl.htmlFor = `option-graphics-${key}`;
    input.id = labelEl.htmlFor;
    for (const [text, value] of choices) {
      const option = node('option', text);
      option.value = value;
      input.append(option);
    }
    input.value = resolveGraphics(settings.graphics, device)[key];
    input.addEventListener('change', () => setGraphic(key, input.value as GraphicsSettings[K]), {
      signal: renderEvents.signal,
    });
    row.append(labelEl, input);
    content.append(row);
  }
  function updateGraphicsStatus() {
    const applying = content.querySelector<HTMLElement>('.graphics-applying');
    if (applying)
      applying.textContent =
        doc.documentElement.dataset.graphicsApplying === 'true' ? 'Applying…' : '';
    const adaptive = content.querySelector<HTMLElement>('.graphics-adaptive');
    if (!adaptive || !graphics) return;
    const active = graphics.effective;
    const labels = {
      frameRate: `Frame rate ${active.frameRate}`,
      lighting: `Lighting ${active.lighting}`,
      resolution: `Resolution ${active.resolution}%`,
      particles: `Particles ${active.particles}`,
      grass: `Grass ${active.grass}`,
    };
    const keys = new Set(graphics.reductions.map((reduction) => reduction.key));
    adaptive.textContent = keys.size
      ? `Adaptive reductions: ${[...keys].map((key) => labels[key]).join(' · ')}`
      : active.adaptive
        ? 'Using your selected quality.'
        : 'Adaptive quality is off.';
  }
  function select<K extends keyof Settings>(
    key: K,
    label: string,
    choices: [string, Settings[K]][],
    help = '',
  ) {
    const row = node('div', '', 'option-row'),
      words = node('div');
    const labelEl = node('label', label);
    labelEl.htmlFor = `option-${key}`;
    words.append(labelEl);
    if (help) words.append(node('small', help));
    const input = node('select');
    input.id = labelEl.htmlFor;
    for (const [text, value] of choices) {
      const opt = node('option', text);
      opt.value = String(value);
      input.append(opt);
    }
    input.value = String(settings[key]);
    input.addEventListener(
      'change',
      () => {
        settings[key] = choices.find(([, v]) => String(v) === input.value)![1];
        persist();
      },
      { signal: renderEvents.signal },
    );
    row.append(words, input);
    content.append(row);
  }
  function checkbox(key: 'muted' | 'vibration', label: string, help = '', disabled = false) {
    const row = node('div', '', 'option-row'),
      words = node('div'),
      labelEl = node('label', label);
    labelEl.htmlFor = `option-${key}`;
    words.append(labelEl);
    if (help) words.append(node('small', help));
    const input = node('input');
    input.type = 'checkbox';
    input.id = labelEl.htmlFor;
    input.checked = settings[key];
    input.disabled = disabled;
    input.addEventListener(
      'change',
      () => {
        settings[key] = input.checked;
        persist();
      },
      { signal: renderEvents.signal },
    );
    row.append(words, input);
    content.append(row);
  }
  function volume(key: 'effectsVolume' | 'ambienceVolume', label: string) {
    const row = node('div', '', 'option-volume'),
      labelEl = node('label', label);
    labelEl.htmlFor = `option-${key}`;
    const output = node('output', `${Math.round(settings[key] * 100)}%`);
    output.htmlFor = labelEl.htmlFor;
    const input = node('input');
    input.id = labelEl.htmlFor;
    input.type = 'range';
    input.min = '0';
    input.max = '100';
    input.step = '5';
    input.value = String(Math.round(settings[key] * 100));
    const update = () => {
      settings[key] = Number(input.value) / 100;
      output.value = `${input.value}%`;
      input.setAttribute('aria-valuetext', output.value);
      persist();
    };
    input.setAttribute('aria-valuetext', output.value);
    input.addEventListener('input', update, { signal: renderEvents.signal });
    row.append(labelEl, output, input);
    content.append(row);
  }
  function navigate(next: Page) {
    capture = null;
    message = '';
    page = next;
    win.history.pushState({ ...win.history.state, issenOptions: historyId, page }, '');
    render(true);
  }
  function back() {
    if (capture) {
      capture = null;
      message = 'Binding change cancelled.';
      render(true);
      return;
    }
    win.history.back();
  }
  function finish() {
    renderEvents.abort();
    open = false;
    doc.documentElement.dataset.graphicsOpen = 'false';
    capture = null;
    root.hidden = true;
    closed();
    origin?.focus({ preventScroll: true });
    const action = afterClose;
    afterClose = null;
    action?.();
  }
  function render(focus = false) {
    doc.documentElement.dataset.graphicsOpen = String(open && page === 'graphics');
    renderEvents.abort();
    renderEvents = new AbortController();
    content.replaceChildren();
    profiles.hidden = page !== 'profile';
    root.scrollTop = 0;
    root.querySelector('.options-box')!.scrollTop = 0;
    const header = node('div', '', 'options-heading'),
      heading = node('h2', TITLES[page]);
    heading.tabIndex = -1;
    header.append(heading, button(page === 'root' ? 'Done' : 'Back', back));
    content.append(header);
    if (page === 'root') {
      content.append(
        node('p', 'Make Issen comfortable to play. Changes are saved as you go.', 'options-intro'),
      );
      const summaries: Record<Category, string> = {
        audio: settings.muted
          ? 'Muted'
          : `Effects ${Math.round(settings.effectsVolume * 100)}% · Ambience ${Math.round(settings.ambienceVolume * 100)}%`,
        controls: `${settings.sensitivity[0]!.toUpperCase() + settings.sensitivity.slice(1)} swipe sensitivity · Keyboard bindings`,
        display: `${settings.textSize === 'large' ? 'Large' : 'Normal'} text · Motion and flashes`,
        graphics: presetLabel(),
        profile: 'Profiles · Save backups',
      };
      for (const category of ['audio', 'controls', 'display', 'graphics', 'profile'] as const) {
        const el = button('', () => navigate(category), 'btn option-category');
        el.append(node('strong', TITLES[category]), node('small', summaries[category]));
        content.append(el);
      }
      if (tutorial)
        content.append(
          button('Tutorial', () => {
            afterClose = tutorial;
            back();
          }),
        );
    } else if (page === 'audio') {
      checkbox('muted', 'Master mute', 'Keep your volume choices while sound is muted.');
      volume('effectsVolume', 'Sound effects');
      volume('ambienceVolume', 'Ambience');
    } else if (page === 'controls') {
      content.append(
        node(
          'p',
          'Swipe to cut. Tap to parry in a duel, or throw a charged knife during a wave. Escape always pauses and closes menus.',
          'options-intro',
        ),
      );
      select(
        'sensitivity',
        'Swipe sensitivity',
        [
          ['Low', 'low'],
          ['Normal', 'normal'],
          ['High', 'high'],
        ],
        'Higher sensitivity needs a shorter swipe. Combat timing stays the same.',
      );
      content.append(node('h3', 'Keyboard bindings'));
      for (const action of CONTROL_ACTIONS) {
        const row = node('div', '', 'option-row'),
          label = node('span', CONTROL_LABELS[action]);
        const key = button(
          capture === action ? 'Press a key…' : settings.bindings[action].map(keyLabel).join(' / '),
          () => {
            capture = action;
            message = 'Press a letter, arrow or Space. Escape cancels.';
            render(true);
          },
        );
        key.setAttribute('aria-label', `Change ${CONTROL_LABELS[action].toLowerCase()} binding`);
        row.append(label, key);
        content.append(row);
      }
      if (capture)
        content.append(
          button('Cancel binding change', () => {
            capture = null;
            message = 'Binding change cancelled.';
            render(true);
          }),
        );
      content.append(
        button('Restore default bindings', () => {
          settings.bindings = defaultSettings().bindings;
          capture = null;
          message = 'Default bindings restored.';
          persist();
          render(true);
        }),
      );
    } else if (page === 'graphics') {
      const metrics = node('p', '', 'graphics-metrics');
      metrics.id = 'graphicsFrameMetrics';
      metrics.textContent = frameMetricsText(
        frameMetrics?.snapshot ?? { active: false, fps: 0, frameMs: 0 },
      );
      content.append(metrics);
      const row = node('div', '', 'option-row');
      const label = node('label', 'Preset');
      label.htmlFor = 'option-graphics-preset';
      const input = node('select');
      input.id = label.htmlFor;
      for (const preset of ['auto', 'low', 'balanced', 'high', 'custom'] as const) {
        const title =
          preset === 'auto'
            ? `Auto (${recommendedGraphics(device) === 'high' ? 'High' : 'Balanced'})`
            : preset[0]!.toUpperCase() + preset.slice(1);
        const option = node('option', title);
        option.value = preset;
        option.disabled = preset === 'custom' && settings.graphics.preset !== 'custom';
        input.append(option);
      }
      input.value = settings.graphics.preset;
      input.addEventListener(
        'change',
        () => {
          const preset = input.value as GraphicsPreset;
          if (preset === 'custom') return;
          settings.graphics = graphicsPreset(preset, device);
          persist();
          render();
        },
        { signal: renderEvents.signal },
      );
      row.append(label, input);
      content.append(row);
      const fpsRow = node('div', '', 'option-row');
      const fpsLabel = node('label', 'Frame rate');
      fpsLabel.htmlFor = 'option-graphics-frameRate';
      const fpsInput = node('select');
      fpsInput.id = fpsLabel.htmlFor;
      const supports120 = doc.documentElement.dataset.supports120 === 'true';
      for (const fps of supports120 ? [30, 60, 120] : [30, 60]) {
        const option = node('option', String(fps));
        option.value = String(fps);
        fpsInput.append(option);
      }
      fpsInput.value = String(graphicsFrameRate(settings.graphics, device, supports120));
      fpsInput.addEventListener(
        'change',
        () => {
          settings.graphics = resolveGraphics(settings.graphics, device);
          setGraphicsOption(
            settings.graphics,
            'frameRate',
            Number(fpsInput.value) as 30 | 60 | 120,
          );
          persist();
          render();
        },
        { signal: renderEvents.signal },
      );
      fpsRow.append(fpsLabel, fpsInput);
      content.append(fpsRow);
      const resolutionRow = node('div', '', 'option-volume');
      const resolutionLabel = node('label', 'Render resolution');
      resolutionLabel.htmlFor = 'option-graphics-resolution';
      const resolution = node('input'),
        resolutionOutput = node('output');
      resolution.id = resolutionLabel.htmlFor;
      resolution.type = 'range';
      resolution.min = '50';
      resolution.max = '100';
      resolution.step = '5';
      resolution.value = String(resolveGraphics(settings.graphics, device).resolution);
      resolutionOutput.htmlFor = resolution.id;
      const showResolution = () => {
        resolutionOutput.value = `${resolution.value}%`;
        resolution.setAttribute('aria-valuetext', resolutionOutput.value);
      };
      showResolution();
      resolution.addEventListener(
        'input',
        () => {
          showResolution();
          setGraphic('resolution', Number(resolution.value));
        },
        { signal: renderEvents.signal },
      );
      resolutionRow.append(resolutionLabel, resolutionOutput, resolution);
      content.append(resolutionRow);
      graphicSelect('lighting', 'Lighting', [
        ['Off', 'off'],
        ['Half', 'half'],
        ['Full', 'full'],
      ]);
      const aaRow = node('div', '', 'option-row'),
        aaLabel = node('label', 'Anti-aliasing'),
        aaInput = node('input');
      aaLabel.htmlFor = 'option-graphics-antialias';
      aaInput.id = aaLabel.htmlFor;
      aaInput.type = 'checkbox';
      aaInput.checked = settings.graphics.antialias;
      aaInput.addEventListener('change', () => setGraphic('antialias', aaInput.checked), {
        signal: renderEvents.signal,
      });
      aaRow.append(aaLabel, aaInput);
      content.append(aaRow);
      graphicSelect('particles', 'Ambient particles', [
        ['Off', 'off'],
        ['Low', 'low'],
        ['Medium', 'medium'],
        ['High', 'high'],
      ]);
      graphicSelect('weather', 'Weather effects', [
        ['Reduced', 'reduced'],
        ['Full', 'full'],
      ]);
      graphicSelect('grass', 'Grass', [
        ['Low', 'low'],
        ['Medium', 'medium'],
        ['High', 'high'],
      ]);
      graphicSelect('scenery', 'Scenery detail', [
        ['Low', 'low'],
        ['Normal', 'normal'],
        ['High', 'high'],
      ]);
      graphicSelect('memory', 'Memory usage', [
        ['Low', 'low'],
        ['Normal', 'normal'],
        ['High', 'high'],
      ]);
      const adaptiveRow = node('div', '', 'option-row'),
        adaptiveLabel = node('label', 'Adaptive quality'),
        adaptiveInput = node('input');
      adaptiveLabel.htmlFor = 'option-graphics-adaptive';
      adaptiveInput.id = adaptiveLabel.htmlFor;
      adaptiveInput.type = 'checkbox';
      adaptiveInput.checked = settings.graphics.adaptive;
      adaptiveInput.addEventListener(
        'change',
        () => {
          setGraphic('adaptive', adaptiveInput.checked);
          updateGraphicsStatus();
        },
        { signal: renderEvents.signal },
      );
      adaptiveRow.append(adaptiveLabel, adaptiveInput);
      const preloadRow = node('div', '', 'option-row'),
        preloadLabel = node('label', 'Preload next stage'),
        preloadInput = node('input');
      preloadLabel.htmlFor = 'option-graphics-preload';
      preloadInput.id = preloadLabel.htmlFor;
      preloadInput.type = 'checkbox';
      preloadInput.checked = settings.graphics.preload;
      preloadInput.addEventListener('change', () => setGraphic('preload', preloadInput.checked), {
        signal: renderEvents.signal,
      });
      preloadRow.append(preloadLabel, preloadInput);
      const counterRow = node('div', '', 'option-row'),
        counterLabel = node('label', 'Show FPS counter'),
        counterInput = node('input');
      counterLabel.htmlFor = 'option-graphics-fps-counter';
      counterInput.id = counterLabel.htmlFor;
      counterInput.type = 'checkbox';
      counterInput.checked = settings.graphics.fpsCounter;
      counterInput.addEventListener(
        'change',
        () => setGraphic('fpsCounter', counterInput.checked),
        { signal: renderEvents.signal },
      );
      counterRow.append(counterLabel, counterInput);
      const adaptiveStatus = node('p', '', 'graphics-adaptive'),
        applying = node('p', '', 'graphics-applying');
      adaptiveStatus.setAttribute('role', 'status');
      applying.setAttribute('role', 'status');
      content.append(
        adaptiveRow,
        preloadRow,
        counterRow,
        adaptiveStatus,
        applying,
        button('Motion and flashes', () => navigate('display')),
      );
      updateGraphicsStatus();
    } else if (page === 'profile') {
      // Persistent controls and modal listeners live outside the rerendered content.
    } else {
      const preferences = [
        ['System', 'system'],
        ['On', 'on'],
        ['Off', 'off'],
      ] as const;
      select(
        'reducedMotion',
        'Reduced motion',
        preferences.map(([a, b]) => [a, b]),
        'Reduce camera movement and death animation motion.',
      );
      select(
        'reducedFlashes',
        'Reduced flashes',
        preferences.map(([a, b]) => [a, b]),
        'Soften screen flashes. System follows your reduced-motion preference.',
      );
      select('textSize', 'Interface text', [
        ['Normal', 'normal'],
        ['Large', 'large'],
      ]);
      select(
        'vibrationStrength',
        'Vibration strength',
        [
          ['Light', 'light'],
          ['Full', 'full'],
        ],
        'Off is controlled by the Vibration switch.',
      );
      const supported = typeof win.navigator.vibrate === 'function';
      checkbox(
        'vibration',
        'Vibration',
        supported
          ? 'Short feedback on cuts, impacts and parries.'
          : 'Vibration is unavailable on this device.',
        !supported,
      );
    }
    const status = node('p', message, 'options-status');
    status.setAttribute('role', 'status');
    content.append(status);
    if (page !== 'root' && page !== 'profile') {
      content.append(node('p', 'Restore defaults resets only this category.', 'options-help'));
      content.append(
        button(page === 'graphics' ? 'Reset to recommended' : 'Restore defaults', () => {
          const defaults = defaultSettings();
          if (page === 'audio') {
            settings.muted = false;
            settings.effectsVolume = 1;
            settings.ambienceVolume = 1;
          }
          if (page === 'controls') {
            settings.sensitivity = 'normal';
            settings.bindings = defaults.bindings;
          }
          if (page === 'display') {
            settings.reducedMotion = 'system';
            settings.reducedFlashes = 'system';
            settings.textSize = 'normal';
            settings.menuStyle = 'scroll';

            settings.vibration = true;
            settings.vibrationStrength = 'full';
          }
          if (page === 'graphics') settings.graphics = graphicsPreset('auto', device);
          capture = null;
          message = `${TITLES[page]} defaults restored.`;
          persist();
          render(true);
        }),
      );
    }
    if (focus) heading.focus({ preventScroll: true });
  }
  win.addEventListener(
    'issen:refresh-rate',
    () => {
      if (open && page === 'graphics') render();
    },
    { signal: events.signal },
  );
  const graphicsObserver = new MutationObserver(updateGraphicsStatus);
  graphicsObserver.observe(doc.documentElement, {
    attributes: true,
    attributeFilter: ['data-graphics-applying', 'data-graphics-reductions'],
  });
  const unsubscribeGraphics = graphics?.subscribe(updateGraphicsStatus);
  const unsubscribeMetrics = frameMetrics?.subscribe(() => {
    if (!open || page !== 'graphics') return;
    const readout = content.querySelector('#graphicsFrameMetrics');
    const text = frameMetricsText(frameMetrics.snapshot);
    if (readout && readout.textContent !== text) readout.textContent = text;
  });
  win.addEventListener(
    'popstate',
    () => {
      if (!open) return;
      const state = win.history.state;
      if (
        state?.issenOptions === historyId &&
        ['root', 'audio', 'controls', 'display', 'graphics', 'profile'].includes(state.page)
      ) {
        page = state.page;
        capture = null;
        message = '';
        render(true);
      } else finish();
    },
    { signal: events.signal },
  );
  win.addEventListener(
    'issen:back',
    () => {
      if (open) back();
    },
    { signal: events.signal },
  );
  win.addEventListener(
    'keydown',
    (event) => {
      if (!open) return;
      if (root.querySelector('dialog[open]')) return;
      // Keep all menu keys away from runtime shortcuts; native control defaults still work.
      event.stopImmediatePropagation();
      if (event.key === 'Escape') {
        event.preventDefault();
        back();
        return;
      }
      if (event.key === 'Tab' && !capture) {
        const controls = Array.from(
          root.querySelectorAll<HTMLElement>(
            'button:not(:disabled), input:not(:disabled):not([type="file"]), select:not(:disabled)',
          ),
        );
        const visible = controls.filter((el) => el.getClientRects().length);
        const current = visible.indexOf(doc.activeElement as HTMLElement);
        event.preventDefault();
        const next =
          current < 0
            ? event.shiftKey
              ? visible.length - 1
              : 0
            : (current + (event.shiftKey ? -1 : 1) + visible.length) % visible.length;
        visible[next]?.focus();
        return;
      }
      if (!capture) return;
      event.preventDefault();
      const error =
        event.ctrlKey || event.altKey || event.metaKey
          ? 'Modifier shortcuts are reserved. Choose a single key.'
          : assignBinding(settings, capture, event.key);
      if (error) {
        message = error;
        render(true);
        return;
      }
      message = `${CONTROL_LABELS[capture]} set to ${keyLabel(settings.bindings[capture][0]!)}.`;
      capture = null;
      persist();
      render(true);
    },
    { capture: true, signal: events.signal },
  );
  return {
    open() {
      historyId = `issen-options-${Date.now()}-${++session}`;
      origin = doc.activeElement instanceof HTMLElement ? doc.activeElement : null;
      open = true;
      root.hidden = false;
      navigate('root');
    },
    back,
    dispose() {
      graphicsObserver.disconnect();
      unsubscribeGraphics?.();
      unsubscribeMetrics?.();
      events.abort();
      renderEvents.abort();
      root.hidden = true;
      open = false;
      doc.documentElement.dataset.graphicsOpen = 'false';
    },
  };
}
